#pragma once
#include "layout_geometry.hpp"
struct NativeLayoutQuad{uint16_t material;std::array<std::array<float,2>,4> positions;std::array<float,8> uv;std::array<uint32_t,4> colors;float alpha;};
// Native single-frame window geometry; references nw4r window topology from doldecomp/ogws.
inline std::vector<NativeLayoutQuad> layoutWindowQuads(const NativeLayoutResource& pose,const std::vector<TextureImage>& textures){
    auto world=layoutWorldPanes(pose);std::vector<NativeLayoutQuad> result;
    for(size_t i=0;i<pose.panes.size();++i){const auto& pane=pose.panes[i];if(pane.kind!="wnd1"||!world[i].visible)continue;assetCheck(pane.windowFrames.size()==1,"Unsupported multi-frame native window mesh");auto material=pane.windowFrames.front().first;assetCheck(material<pose.materials.size(),"Unknown window border material");const auto& maps=pose.materials[material].textures;assetCheck(maps.size()==1&&maps[0].texture<textures.size(),"Unsupported window border texture binding");const auto& texture=textures[maps[0].texture];float bx=float(texture.width),by=float(texture.height),w=pane.size[0],h=pane.size[1];assetCheck(bx>0&&by>0&&w>=2*bx&&h>=2*by,"Window smaller than frame borders");
        auto emit=[&](uint16_t mat,float x,float y,float width,float height,std::array<float,8> uv,std::array<uint32_t,4> colors){if(width==0||height==0)return;assetCheck(width>0&&height>0,"Invalid window quad dimensions");float left=-float(pane.base%3)*w*.5f+x,top=float(pane.base/3)*h*.5f-y;NativeLayoutQuad quad{mat,{},uv,colors,world[i].alpha};std::array<std::array<float,2>,4> corners{{{left,top},{left+width,top},{left,top-height},{left+width,top-height}}};const auto& m=world[i].matrix;for(unsigned k=0;k<4;++k)quad.positions[k]={m[0]*corners[k][0]+m[1]*corners[k][1]+m[2],m[3]*corners[k][0]+m[4]*corners[k][1]+m[5]};result.push_back(quad);};
        assetCheck(pane.uv.size()==1,"Unsupported window content UV count");emit(pane.material,bx-pane.inflation[0],by-pane.inflation[2],w-2*bx+pane.inflation[0]+pane.inflation[1],h-2*by+pane.inflation[2]+pane.inflation[3],pane.uv.front(),pane.colors);
        std::array<std::array<float,4>,4> rects{{{0,0,w-bx,by},{w-bx,0,bx,h-by},{bx,h-by,w-bx,by},{0,by,bx,h-by}}};std::array<uint32_t,4> white{0xFFFFFFFF,0xFFFFFFFF,0xFFFFFFFF,0xFFFFFFFF};
        for(unsigned side=0;side<4;++side){auto r=rects[side];float u=r[2]/bx,v=r[3]/by;std::array<float,8> uv{};for(unsigned corner=0;corner<4;++corner){bool right=(corner&1)!=0,bottom=(corner&2)!=0;if(side==1||side==2)right=!right;if(side==2||side==3)bottom=!bottom;uv[corner*2]=right?u:0;uv[corner*2+1]=bottom?v:0;}emit(material,r[0],r[1],r[2],r[3],uv,white);}
    }return result;
}
inline void layoutWindowMeshTests(){
    NativeLayoutResource layout;NativeLayoutPane pane;pane.kind="wnd1";pane.flags=1;pane.scale={1,1};pane.size={30,30};pane.base=4;pane.uv={{0,0,1,0,0,1,1,1}};pane.windowFrames={{0,0}};layout.panes={pane};NativeLayoutMaterial material;material.textures={{0,0,0}};layout.materials={material};TextureImage texture{};texture.width=texture.height=8;auto mesh=layoutWindowQuads(layout,{texture});assetCheck(mesh.size()==5,"Single-frame window quad count mismatch");float area=0;for(const auto& q:mesh)area+=(q.positions[1][0]-q.positions[0][0])*(q.positions[0][1]-q.positions[2][1]);assetCheck(area==900,"Window content/borders do not tile bounds");layout.panes[0].size={16,16};assetCheck(layoutWindowQuads(layout,{texture}).size()==4,"Collapsed window content produced geometry");
}
